<script setup lang="ts">
import { computed, reactive, ref } from "vue"; import {useRoute} from "vue-router";
import AppShell from "@/components/zs/AppShell.vue"; import PageHeader from "@/components/zs/PageHeader.vue"; import Panel from "@/components/zs/Panel.vue"; import Tabs from "@/components/zs/Tabs.vue"; import StatusBadge from "@/components/zs/StatusBadge.vue"; import ZButton from "@/components/zs/ZButton.vue"; import ActivityTimeline from "@/components/crm/ActivityTimeline.vue"; import SidePanel from "@/components/zs/SidePanel.vue"; import Field from "@/components/zs/Field.vue"; import AsyncSection from "@/components/zs/AsyncSection.vue"; import ValidationMessage from "@/components/zs/ValidationMessage.vue";
import {useCrmData} from "@/composables/useCrmData"; import {useAsyncData,useMutation} from "@/composables/useAsyncData"; import {crmRepository} from "@/services/crm/repository"; import {formatMoney} from "@/lib/money"; import {showToast} from "@/composables/useToast"; import {setPageMeta} from "@/lib/page-meta";
setPageMeta("Deal Detail","Commercial terms, stage, customer handoff and activity.");const route=useRoute(),data=useCrmData(),id=computed(()=>String(route.params.id)),state=useAsyncData(()=>crmRepository.deal(data.activeCompanyId.value,id.value),{watch:[data.activeCompanyId,id]}),item=computed(()=>state.data.value),tab=ref("Overview"),activityOpen=ref(false),handoffOpen=ref(false);const activities=computed(()=>(data.activities.data.value??[]).filter((activity)=>activity.dealId===id.value));const pipeline=computed(()=>data.pipelines.data.value?.find((entry)=>entry.id===item.value?.pipelineId));
const transitionMutation=useMutation((stageId:string,lossReason?:string)=>crmRepository.transitionDeal(data.activeCompanyId.value,id.value,stageId,lossReason));async function transition(stageId:string){const stage=pipeline.value?.stages.find((entry)=>entry.id===stageId);const lossReason=stage?.isLost?window.prompt("Loss reason (required)")?.trim():undefined;if(stage?.isLost&&!lossReason)return;const saved=await transitionMutation.run(stageId,lossReason);if(!saved)return;await Promise.all([state.refresh(),data.deals.refresh(),data.dashboard.refresh()]);showToast("Deal stage updated",saved.stage,"success");}
const activity=reactive({type:"CALL",subject:"",description:"",due_at:"",priority:"MEDIUM"});const activityMutation=useMutation(()=>crmRepository.createActivity(data.activeCompanyId.value,{...activity,related_type:"deal",related_id:id.value,status:"PENDING"}));async function logActivity(){const saved=await activityMutation.run();if(!saved)return;activityOpen.value=false;await data.activities.refresh();showToast("Activity saved",saved.subject,"success");}
const matches=useAsyncData(()=>item.value?crmRepository.customerMatches(data.activeCompanyId.value,item.value.accountId):Promise.resolve([]),{watch:[item],immediate:true});const handoff=reactive({customer_id:"",name:"",email:"",phone:"",ntn:"",cnic:"",address:"",city:"",country:"PK",currency:"PKR",type:"BUSINESS",is_active:true});const handoffMutation=useMutation(()=>crmRepository.handoffDeal(data.activeCompanyId.value,id.value,{...handoff,customer_id:handoff.customer_id||null}));function prepareHandoff(){Object.assign(handoff,{customer_id:"",name:item.value?.company??"",email:"",phone:"",ntn:"",cnic:"",address:"",city:"",country:"PK",currency:"PKR",type:"BUSINESS",is_active:true});handoffOpen.value=true;void matches.refresh();}async function handoffCustomer(){const customer=await handoffMutation.run();if(!customer)return;handoffOpen.value=false;await Promise.all([state.refresh(),data.deals.refresh(),data.companies.refresh()]);showToast("Customer handoff complete",`${customer.name} is linked to accounting.`,"success");}
</script>
<template><AppShell><AsyncSection :loading="state.loading.value" :error="state.error.value" @retry="state.refresh"><template v-if="item"><PageHeader :title="item.name" :description="`${item.company} · ${formatMoney(item.value,item.currency)}`"><template #actions><StatusBadge :status="item.status"/><ZButton variant="outline" @click="activityOpen=true">Log activity</ZButton><ZButton v-if="item.status==='WON'&&!item.customerId" @click="prepareHandoff">Create customer</ZButton></template></PageHeader><div class="grid gap-4 xl:grid-cols-[1fr_20rem]"><Panel><Tabs v-model="tab" :items="['Overview','Activity','Notes']"/><div v-if="tab==='Overview'" class="grid gap-5 p-5 sm:grid-cols-2"><div v-for="[key,value] in Object.entries({Company:item.company,Contact:item.contact||'—',Pipeline:item.pipeline,Stage:item.stage,Value:formatMoney(item.value,item.currency),Probability:`${item.probability}%`,'Weighted value':formatMoney(item.weightedValue,item.currency),'Expected close':item.expectedClose||'—',Owner:item.owner||'Unassigned',Source:item.source||'—'})" :key="key"><p class="label-caps">{{key}}</p><p class="mt-1 text-sm text-content">{{value}}</p></div></div><div v-else-if="tab==='Activity'" class="p-4"><ActivityTimeline :items="activities"/></div><div v-else class="p-5 text-sm text-content-secondary">{{item.description||'No notes recorded.'}}</div></Panel><div class="space-y-4"><Panel title="Pipeline stage"><div class="p-4"><select :value="item.pipelineStageId" class="field" :disabled="transitionMutation.saving.value" @change="transition(($event.target as HTMLSelectElement).value)"><option v-for="stage in pipeline?.stages??[]" :key="stage.id" :value="stage.id">{{stage.name}}</option></select><ValidationMessage :message="transitionMutation.error.value?.message"/></div></Panel><Panel title="Stage probability"><div class="p-4"><div class="h-2 rounded-full bg-surface-sunken"><div class="h-full rounded-full bg-primary" :style="{width:`${item.probability}%`}"/></div><p class="num mt-2 text-right text-xs text-content-secondary">{{item.probability}}%</p></div></Panel><Panel v-if="item.customerId" title="Accounting customer"><p class="p-4 text-sm text-success">Customer linked</p></Panel></div></div></template></AsyncSection><SidePanel :open="activityOpen" title="Log deal activity" @close="activityOpen=false"><form class="grid gap-4" @submit.prevent="logActivity"><label><span class="label-caps">Type</span><select v-model="activity.type" class="field mt-1.5"><option>CALL</option><option>MEETING</option><option>EMAIL</option><option>TASK</option><option>NOTE</option></select></label><Field v-model="activity.subject" label="Subject" required/><Field v-model="activity.due_at" label="Due at" type="datetime-local"/><label><span class="label-caps">Description</span><textarea v-model="activity.description" class="field mt-1.5 min-h-20"/></label><ValidationMessage :message="activityMutation.error.value?.message"/><ZButton type="submit">Save activity</ZButton></form></SidePanel><SidePanel :open="handoffOpen" title="Customer handoff" description="Link an existing accounting customer or create one from this won deal." @close="handoffOpen=false"><form class="grid gap-4 sm:grid-cols-2" @submit.prevent="handoffCustomer"><label class="sm:col-span-2"><span class="label-caps">Existing match</span><select v-model="handoff.customer_id" class="field mt-1.5"><option value="">Create a new customer</option><option v-for="customer in matches.data.value??[]" :key="customer.id" :value="customer.id">{{customer.name}} · {{customer.email}}</option></select></label><template v-if="!handoff.customer_id"><Field v-model="handoff.name" label="Customer name" required/><Field v-model="handoff.email" label="Email" type="email"/><Field v-model="handoff.phone" label="Phone"/><Field v-model="handoff.ntn" label="NTN"/><Field v-model="handoff.cnic" label="CNIC"/><Field v-model="handoff.city" label="City"/><label class="sm:col-span-2"><span class="label-caps">Address</span><textarea v-model="handoff.address" class="field mt-1.5 min-h-20"/></label></template><ValidationMessage class="sm:col-span-2" :message="handoffMutation.error.value?.message"/><ZButton class="sm:col-span-2" type="submit" :disabled="handoffMutation.saving.value">Complete handoff</ZButton></form></SidePanel></AppShell></template>
